// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 deposit, uint256 am) public {
        vm.assume(deposit <= VALUE_CAP);
        deposit = bound(deposit, c.MinSum(), type(uint128).max);
        am = bound(am, 1, deposit - 1);

        vm.deal(address(this), deposit);
        c.Put{value: deposit}(0);

        ( , uint256 beforeBal) = c.Acc(address(this));
        assertEq(beforeBal, deposit);

        vm.warp(block.timestamp + 1);
        c.Collect(am);

        ( , uint256 afterBal) = c.Acc(address(this));
        assertTrue(afterBal == beforeBal - am, "partial collect must subtract exactly am, not zero the balance");
    }

    receive() external payable {}
}
